function validOtp(v: unknown): v is string { return typeof v === "string" && /^\d{6}$/.test(v); }
function validEmail(v: unknown): v is string { return typeof v === "string" && /^[^\s@]{1,64}@[^\s@]{1,190}\.[^\s@]{2,63}$/.test(v); }
